Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Ltac fi_u8fix := lazymatch goal with
  | |- evt _ _ (MS _ _ _ _ _ (write_to_mem ?m _ _) _) =>
    rewrite ?le1_lit;
    lazymatch goal with
    | H : u8arr rsegs m ?A ?xs |- context [write_to_mem m (Z_to_bv 64 (?A + ?k)) [?b]] =>
        let BU' := fresh "BU" in
        pose proof (u8arr_write rsegs m A xs k b H ltac:(rewrite ?upd_length; lia)) as BU'; clear H; store_done
    | H : u8arr rsegs m ?A ?xs |- context [write_to_mem m (wa (?A + ?k)) [?b]] =>
        let BU' := fresh "BU" in
        pose proof (u8arr_write rsegs m A xs k b H ltac:(rewrite ?upd_length; lia)) as BU'; clear H; store_done
    end
  | _ => idtac
  end.
Ltac fi_xstep := first [ zstep; fi_u8fix | if_true | if_false ].
Ltac fi_at p := lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 ?x) _ _ _ _) => constr_eq x p end.
Ltac fi_run p q := repeat (tryif (first [fi_at p | fi_at q]) then fail else fi_xstep).
Ltac fi_solve d p q :=
  lazymatch d with
  | O => fail 100 "fi_solve: out of fuel"
  | S ?d' =>
    fi_run p q;
    tryif (first [fi_at p | fi_at q]) then idtac
    else lazymatch goal with
    | |- evt _ _ (MS _ _ (if _ then _ else _) _ _ _ _) =>
        let K := fresh "K" in if_cases K; zify_cond K;
        [ first [ exfalso; lia | fi_solve d' p q ] | first [ exfalso; lia | fi_solve d' p q ] ]
    end
  end.

Lemma div10_pow : forall x k, (0 <= k)%Z -> (0 <= x < 10 ^ (k + 1))%Z -> (0 <= x / 10 < 10 ^ k)%Z.
Proof.
  intros x k Hk Hx. rewrite Z.pow_add_r, Z.pow_1_r in Hx by lia. pose proof (Z.pow_pos_nonneg 10 k ltac:(lia) Hk).
  split; [apply Z.div_pos; lia|]. apply Z.div_lt_upper_bound; lia.
Qed.
Lemma pow10_mono : forall a b, (0 <= a <= b)%Z -> (10 ^ a <= 10 ^ b)%Z.
Proof. intros a b H. apply Z.pow_le_mono_r; lia. Qed.

