Lemma nq_val : forall w, (2 ^ 63 <= w <= 2 ^ 64 - 10)%Z ->
  Z_to_bv 64 (bv_signed (Z_to_bv 64 ((bv_signed (Z_to_bv 64 w) * bv_signed (Z_to_bv 64 FM2)) ≫ 64)) ≫ 2 +
