Variable m0 : word -> option byte.
Hypothesis SPR : (2 ^ 41 + 8816 <= SP /\ SP <= 2 ^ 47)%Z.
Hypothesis SKR : (0 <= SK < 2 ^ 64)%Z.
Definition FSP : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!2'^W/SP;!1,0|840;").
Definition BUF : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!2'^A'_U!1,0|49;").
Definition FI_W : list (Z * Z) := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!2+_V+1+1!3,Z0!4,_W+1+1!2'^W/SP;!1,0|=0270;/SP;!1,D0").

(* [comment removed for export] *)
Definition fi_mem (m : word -> option byte) (jl bsb : list byte) : Prop :=
  rw_cells rsegs m FSP [CB 25 jl] /\ u8arr rsegs m BUF bsb /\ length bsb = 255%nat
  /\ rw_cells rsegs m (FSP + 280) [C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
  /\ stk rsegs m (SP - 8816) FSP /\ munch FI_W m0 m /\ wmono rsegs m0 m /\ mem_inv rsegs m.

(* [comment removed for export] *)
Definition fi64_post (v : Z) : machine_state -> Prop :=
  fun ms' => exists t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m' (c : Z) (jl bsb : list byte),
    ms' = MS (mkR ra (Z_to_bv 64 FSP) gp tp t0' t1' t2' (Z_to_bv 64 SK) s1 (Z_to_bv 64 v) a1' a2' a3' a4' a5' a6' a7' (Z_to_bv 64 c) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
             F (Z_to_bv 64 0x3ed18) fc None m' (seg_rom rsegs)
    /\ (1 <= c <= 19)%Z /\ fi_mem m' jl bsb.
(* [comment removed for export] *)
Definition fiu_post : machine_state -> Prop :=
  fun ms' => exists t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m' (c : Z) (jl bsb : list byte),
    ms' = MS (mkR ra (Z_to_bv 64 FSP) gp tp t0' t1' t2' (Z_to_bv 64 SK) (Z_to_bv 64 c) a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
             F (Z_to_bv 64 0x3eb5c) fc None m' (seg_rom rsegs)
    /\ (1 <= c <= 20)%Z /\ fi_mem m' jl bsb.

(* [comment removed for export] *)
Lemma fi_ploop : forall (n : nat) (x i : Z) t0 t1 t2 a6 a7 t3 t4 t5 t6 (m : word -> option byte) (v : Z) (jl bsb : list byte),
  Z.to_nat (18 - i) = n -> (0 <= i <= 18)%Z -> (0 <= x < 10 ^ (19 - i))%Z -> (0 <= v < 2 ^ 64)%Z ->
  fi_mem m jl bsb ->
  evt rsegs (fi64_post v) (MS (mkR ra (Z_to_bv 64 FSP) gp tp t0 t1 t2 (Z_to_bv 64 SK) s1 (Z_to_bv 64 v) (Z_to_bv 64 FM1) (Z_to_bv 64 BUF)
                              (Z_to_bv 64 10) (Z_to_bv 64 254) (Z_to_bv 64 x) a6 a7 (Z_to_bv 64 i) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                         F (Z_to_bv 64 0x3ec8c) fc None m (seg_rom rsegs)).
Proof.
  induction n as [|n IH]; intros x i t0 t1 t2 a6 a7 t3 t4 t5 t6 m v jl bsb Hn Hi Hx Hv FM;
    destruct FM as (CJ & BU & BL & CS & ST & MU & WM & MI); unfold FI_W in MU;
    assert (EF : FSP = (SP - 320)%Z) by (unfold FSP; lia); assert (EB : BUF = (SP - 295)%Z) by (unfold BUF; lia);
    assert (HS : store_ok rsegs m (wa (BUF + i)) 1 = true)
      by (apply (u8arr_store_ok rsegs m BUF bsb i); [exact BU | lia | reflexivity]);
    pose proof (pow10_mono (19 - i) 19 ltac:(lia)) as P19;
    assert (X64 : (x < 18446744073709551616)%Z)
      by (assert (T : (10 ^ 19 < 18446744073709551616)%Z) by (vm_compute; reflexivity); lia).
  - assert (Ei : i = 18%Z) by lia. subst i. replace (10 ^ (19 - 18))%Z with 10%Z in Hx by reflexivity.
    fi_xstep. fi_solve 6%nat 0x3ec8c%Z 0x3ed18%Z.
    all: fi_at 0x3ed18%Z; apply evt_done; unfold fi64_post; repeat (lazymatch goal with |- ex _ => eexists end);
      split; [reflexivity|]; split; [lia|];
      unfold fi_mem, FI_W; refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ _))))))); try eassumption;
      rewrite upd_length; exact BL.
  - fi_xstep. fi_solve 6%nat 0x3ec8c%Z 0x3ed18%Z.
    all: first
      [ fi_at 0x3ed18%Z; apply evt_done; unfold fi64_post; repeat (lazymatch goal with |- ex _ => eexists end);
        split; [reflexivity|]; split; [lia|];
        unfold fi_mem, FI_W; refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ _))))))); try eassumption;
        rewrite upd_length; exact BL
      | fi_at 0x3ec8c%Z; try rewrite (Z.mod_small x 18446744073709551616) by lia; rewrite mulhu10 by lia;
        eapply (IH (x / 10) (i + 1))%Z; [lia | lia | | exact Hv | ];
        [ apply div10_pow; [lia|]; replace (19 - (i + 1) + 1)%Z with (19 - i)%Z by lia; exact Hx
        | unfold fi_mem, FI_W; refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ _))))))); try eassumption;
          rewrite upd_length; exact BL ] ].
Qed.
(* [comment removed for export] *)
Lemma fi_nloop : forall (n : nat) (w i : Z) t0 t1 t2 a6 t3 t4 t5 t6 (m : word -> option byte) (v : Z) (jl bsb : list byte),
  Z.to_nat (18 - i) = n -> (0 <= i <= 18)%Z -> (2 ^ 63 <= w < 2 ^ 64)%Z -> (2 ^ 64 - w < 10 ^ (19 - i))%Z -> (0 <= v < 2 ^ 64)%Z ->
  fi_mem m jl bsb ->
  evt rsegs (fi64_post v) (MS (mkR ra (Z_to_bv 64 FSP) gp tp t0 t1 t2 (Z_to_bv 64 SK) s1 (Z_to_bv 64 v) (Z_to_bv 64 BUF) (Z_to_bv 64 FM2)
                              (Z_to_bv 64 10) (Z_to_bv 64 (-20)) (Z_to_bv 64 254) a6 (Z_to_bv 64 w) (Z_to_bv 64 i) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                         F (Z_to_bv 64 0x3ecdc) fc None m (seg_rom rsegs)).
Proof.
  induction n as [|n IH]; intros w i t0 t1 t2 a6 t3 t4 t5 t6 m v jl bsb Hn Hi Hw Hw2 Hv FM;
    destruct FM as (CJ & BU & BL & CS & ST & MU & WM & MI); unfold FI_W in MU;
    assert (EF : FSP = (SP - 320)%Z) by (unfold FSP; lia); assert (EB : BUF = (SP - 295)%Z) by (unfold BUF; lia);
    assert (HS : store_ok rsegs m (wa (BUF + i)) 1 = true)
      by (apply (u8arr_store_ok rsegs m BUF bsb i); [exact BU | lia | reflexivity]).
  - assert (Ei : i = 18%Z) by lia. subst i. replace (10 ^ (19 - 18))%Z with 10%Z in Hw2 by reflexivity.
    fi_xstep. fi_solve 6%nat 0x3ecdc%Z 0x3ed18%Z.
    all: fi_at 0x3ed18%Z; apply evt_done; unfold fi64_post; repeat (lazymatch goal with |- ex _ => eexists end);
      split; [reflexivity|]; split; [lia|];
      unfold fi_mem, FI_W; refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ _))))))); try eassumption;
      rewrite upd_length; exact BL.
  - fi_xstep. fi_solve 6%nat 0x3ecdc%Z 0x3ed18%Z.
    all: first
      [ fi_at 0x3ed18%Z; apply evt_done; unfold fi64_post; repeat (lazymatch goal with |- ex _ => eexists end);
        split; [reflexivity|]; split; [lia|];
        unfold fi_mem, FI_W; refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ _))))))); try eassumption;
        rewrite upd_length; exact BL
      | fi_at 0x3ecdc%Z; rewrite nq_val by lia;
        eapply (IH (2 ^ 64 - (2 ^ 64 - w) / 10) (i + 1))%Z; [lia | lia | Z.div_mod_to_equations; lia | | exact Hv | ];
        [ replace (2 ^ 64 - (2 ^ 64 - (2 ^ 64 - w) / 10))%Z with ((2 ^ 64 - w) / 10)%Z by lia;
          apply div10_pow; [lia|]; replace (19 - (i + 1) + 1)%Z with (19 - i)%Z by lia; lia
        | unfold fi_mem, FI_W; refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ _))))))); try eassumption;
          rewrite upd_length; exact BL ] ].
Qed.

