Lemma fi_frame : forall m (junk : list byte),
  rw_cells rsegs m (SP + -320) [CB 280 (firstn 280 (firstn 288 (firstn 296 (firstn 304 (firstn 312 junk))))); C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  stk rsegs m (SP - 8816) (SP + -320) -> munch [(SP - 8816, SP)]%Z m0 m -> wmono rsegs m0 m -> mem_inv rsegs m ->
  exists jl bsb, fi_mem m jl bsb.
