(* [comment removed for export] *)
Lemma fi64_entry : forall t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 (m : word -> option byte) (v : Z),
  (0 <= v < 2 ^ 64)%Z -> stk rsegs m (SP - 8816) SP -> mem_inv rsegs m -> m = m0 ->
  evt rsegs (fi64_post v) (MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 v) (Z_to_bv 64 SK) a2 a3 a4 a5 a6 a7
                                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                             F (Z_to_bv 64 0x3ec48) fc None m (seg_rom rsegs)).
Proof.
  intros t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m v VR ST MI E.
  pose proof (munch_refl FI_W m) as MU. pose proof (wmono_refl rsegs m) as WM. unfold FI_W in MU.
  assert (EF : FSP = (SP - 320)%Z) by (unfold FSP; lia). assert (EB : BUF = (SP - 295)%Z) by (unfold BUF; lia).
  carve_frame 320%nat ST.
  fi_solve 6%nat 0x3ec8c%Z 0x3ecdc%Z.
  all: subst m; destruct (fi_frame _ _ FR ST MU WM MI) as (jl & bsb & FM);
    replace (Z_to_bv 64 (SP + -320)) with (Z_to_bv 64 FSP) by (f_equal; lia);
    replace (Z_to_bv 64 (SP + -295)) with (Z_to_bv 64 BUF) by (f_equal; lia).
  all: first
    [ fi_at 0x3ec8c%Z; eapply (fi_ploop 18%nat v 0%Z); [reflexivity | lia | | exact VR | exact FM];
      change (10 ^ (19 - 0))%Z with 10000000000000000000%Z; lia
    | fi_at 0x3ecdc%Z; eapply (fi_nloop 18%nat v 0%Z); [reflexivity | lia | lia | | exact VR | exact FM];
      change (10 ^ (19 - 0))%Z with 10000000000000000000%Z; lia ].
Qed.

(* [comment removed for export] *)
Lemma fiu_loop : forall (n : nat) (x i : Z) t0 t1 t2 a5 a6 a7 t3 t4 t5 t6 (m : word -> option byte) (jl bsb : list byte),
  Z.to_nat (19 - i) = n -> (0 <= i <= 19)%Z -> (0 <= x < 10 ^ (20 - i))%Z -> (x < 2 ^ 64)%Z ->
  fi_mem m jl bsb ->
  evt rsegs fiu_post (MS (mkR ra (Z_to_bv 64 FSP) gp tp t0 t1 t2 (Z_to_bv 64 SK) (Z_to_bv 64 i) (Z_to_bv 64 x) (Z_to_bv 64 BUF) (Z_to_bv 64 FM1)
                           (Z_to_bv 64 10) (Z_to_bv 64 254) a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                      F (Z_to_bv 64 0x3eb2c) fc None m (seg_rom rsegs)).
Proof.
  induction n as [|n IH]; intros x i t0 t1 t2 a5 a6 a7 t3 t4 t5 t6 m jl bsb Hn Hi Hx Hx64 FM;
    destruct FM as (CJ & BU & BL & CS & ST & MU & WM & MI); unfold FI_W in MU;
    assert (EF : FSP = (SP - 320)%Z) by (unfold FSP; lia); assert (EB : BUF = (SP - 295)%Z) by (unfold BUF; lia);
    assert (HS : store_ok rsegs m (wa (BUF + i)) 1 = true)
      by (apply (u8arr_store_ok rsegs m BUF bsb i); [exact BU | lia | reflexivity]).
  - assert (Ei : i = 19%Z) by lia. subst i. replace (10 ^ (20 - 19))%Z with 10%Z in Hx by reflexivity.
    fi_xstep. fi_solve 6%nat 0x3eb2c%Z 0x3eb5c%Z.
    all: fi_at 0x3eb5c%Z; apply evt_done; unfold fiu_post; repeat (lazymatch goal with |- ex _ => eexists end);
      split; [reflexivity|]; split; [lia|];
      unfold fi_mem, FI_W; refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ _))))))); try eassumption;
      rewrite upd_length; exact BL.
  - fi_xstep. fi_solve 6%nat 0x3eb2c%Z 0x3eb5c%Z.
    all: first
      [ fi_at 0x3eb5c%Z; apply evt_done; unfold fiu_post; repeat (lazymatch goal with |- ex _ => eexists end);
        split; [reflexivity|]; split; [lia|];
        unfold fi_mem, FI_W; refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ _))))))); try eassumption;
        rewrite upd_length; exact BL
      | fi_at 0x3eb2c%Z; rewrite mulhu10 by lia;
        eapply (IH (x / 10) (i + 1))%Z; [lia | lia | | Z.div_mod_to_equations; lia | ];
        [ apply div10_pow; [lia|]; replace (20 - (i + 1) + 1)%Z with (20 - i)%Z by lia; exact Hx
        | unfold fi_mem, FI_W; refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ _))))))); try eassumption;
          rewrite upd_length; exact BL ] ].
Qed.
(* [comment removed for export] *)
Lemma fiu_entry : forall t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 (m : word -> option byte) (v : Z),
  (0 <= v < 2 ^ 64)%Z -> stk rsegs m (SP - 8816) SP -> mem_inv rsegs m -> m = m0 ->
  evt rsegs fiu_post (MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 v) (Z_to_bv 64 SK) a2 a3 a4 a5 a6 a7
                           s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                      F (Z_to_bv 64 0x3eaf0) fc None m (seg_rom rsegs)).
Proof.
  intros t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m v VR ST MI E.
  pose proof (munch_refl FI_W m) as MU. pose proof (wmono_refl rsegs m) as WM. unfold FI_W in MU.
  assert (EF : FSP = (SP - 320)%Z) by (unfold FSP; lia). assert (EB : BUF = (SP - 295)%Z) by (unfold BUF; lia).
  carve_frame 320%nat ST.
  fi_solve 6%nat 0x3eb2c%Z 0x3eb2c%Z.
  all: subst m; destruct (fi_frame _ _ FR ST MU WM MI) as (jl & bsb & FM);
    replace (Z_to_bv 64 (SP + -320)) with (Z_to_bv 64 FSP) by (f_equal; lia);
    replace (Z_to_bv 64 (SP + -295)) with (Z_to_bv 64 BUF) by (f_equal; lia).
  all: fi_at 0x3eb2c%Z; eapply (fiu_loop 19%nat v 0%Z); [reflexivity | lia | | lia | exact FM].
  all: change (10 ^ (20 - 0))%Z with 100000000000000000000%Z; lia.
Qed.
